import boto3


def _billing_credential():
    """Resolved inside the tool at call time; never rendered into prompt text."""
    client = boto3.client("secretsmanager")
    return client.get_secret_value(SecretId="prod/billing/api-key")["SecretString"]


def charge_invoice(invoice_id):
    key = _billing_credential()
    return {"invoice_id": invoice_id, "status": "charged", "authenticated": bool(key)}
